1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	
5	import '../../../../core/design_tokens.dart';
6	
7	/// Tela 0.1b/0.1c's PIN entry component (prototype-extract.md §2.1/§6,
8	/// UX-DR14): 4 progress dots above a 3×4 numeric grid + backspace.
9	///
10	/// Owns its own digit buffer — the caller never resets it. After the 4th
11	/// digit, it waits 350ms with no explicit confirm tap (UX-DR14), then
12	/// clears the buffer and calls [onSubmit] with the 4-digit string. The
13	/// buffer is cleared *before* [onSubmit] is invoked, regardless of what
14	/// the caller later does with the result, so the keypad is always ready
15	/// for another attempt — the I/O matrix's "keypad clears for another
16	/// attempt — never a dead end".
17	///
18	/// Structural palette only (Boundaries: "no accent on digits") — every
19	/// color below is [DesignTokens.colorSurfaceElevated]/[DesignTokens.
20	/// colorBorder]/[DesignTokens.colorTextPrimary]/[DesignTokens.
21	/// colorTextSecondary]/[DesignTokens.colorPrimary], never [DesignTokens.
22	/// colorAccent]. Every button is at least [DesignTokens.pinKeypadButtonSize]
23	/// (UX-DR23: ≥44pt tap targets). Digit glyphs are wrapped in a
24	/// [FittedBox] so the largest Dynamic Type size shrinks them to fit rather
25	/// than clipping or truncating (UX-DR22).
26	class PinKeypad extends StatefulWidget {
27	  const PinKeypad({required this.onSubmit, this.enabled = true, super.key});
28	
29	  /// Invoked once, 350ms after the 4th digit — never while a 1st-3rd digit
30	  /// is the most recent entry.
31	  final ValueChanged<String> onSubmit;
32	
33	  /// When `false`, every digit/backspace tap is ignored. The caller sets
34	  /// this while a previous [onSubmit] call is still being resolved, so a
35	  /// fast second entry can't build up and silently race the in-flight
36	  /// submission (review finding: the buffer clears for a new attempt
37	  /// immediately after auto-advance, before the caller's own async work
38	  /// finishes).
39	  final bool enabled;
40	
41	  /// The epic's one PIN length — no screen anywhere in `docs/input/`
42	  /// shows a different digit count.
43	  static const int pinLength = 4;
44	
45	  @override
46	  State<PinKeypad> createState() => _PinKeypadState();
47	}
48	
49	class _PinKeypadState extends State<PinKeypad> {
50	  final List<String> _digits = [];
51	  Timer? _advanceTimer;
52	
53	  @override
54	  void dispose() {
55	    _advanceTimer?.cancel();
56	    super.dispose();
57	  }
58	
59	  void _onDigitTap(String digit) {
60	    if (!widget.enabled) {
61	      return;
62	    }
63	    if (_digits.length >= PinKeypad.pinLength) {
64	      // Defensive — the 350ms auto-advance window already clears the
65	      // buffer before a 5th tap could land, but a very fast double-tap on
66	      // the same frame must still never overflow past pinLength.
67	      return;
68	    }
69	    setState(() => _digits.add(digit));
70	    if (_digits.length == PinKeypad.pinLength) {
71	      final pin = _digits.join();
72	      _advanceTimer = Timer(const Duration(milliseconds: 350), () {
73	        if (!mounted) {
74	          return;
75	        }
76	        setState(_digits.clear);
77	        widget.onSubmit(pin);
78	      });
79	    }
80	  }
81	
82	  void _onBackspaceTap() {
83	    if (!widget.enabled) {
84	      return;
85	    }
86	    // Unconditional, before the `isEmpty` check below — a backspace
87	    // during the 350ms auto-advance window must always invalidate the
88	    // scheduled submit, even though the buffer itself isn't touched until
89	    // after this. Without this, a correction typed inside that window
90	    // would be silently discarded: the stale pre-backspace `pin` string
91	    // still fires via `onSubmit` once the timer elapses, and its own
92	    // `setState(_digits.clear)` wipes whatever the user had re-typed by
93	    // then.
94	    _advanceTimer?.cancel();
95	    if (_digits.isEmpty) {
96	      return;
97	    }
98	    setState(_digits.removeLast);
99	  }
100	
101	  @override
102	  Widget build(BuildContext context) {
103	    return Column(
104	      mainAxisSize: MainAxisSize.min,
105	      children: [
106	        _ProgressDots(filledCount: _digits.length),
107	        const SizedBox(height: DesignTokens.spacingLg),
108	        _KeypadGrid(
109	          onDigitTap: _onDigitTap,
110	          onBackspaceTap: _onBackspaceTap,
111	          enabled: widget.enabled,
112	        ),
113	      ],
114	    );
115	  }
116	}
117	
118	class _ProgressDots extends StatelessWidget {
119	  const _ProgressDots({required this.filledCount});
120	
121	  final int filledCount;
122	
123	  @override
124	  Widget build(BuildContext context) {
125	    return Semantics(
126	      label: '$filledCount de ${PinKeypad.pinLength} dígitos do PIN',
127	      child: Row(
128	        mainAxisSize: MainAxisSize.min,
129	        children: List.generate(PinKeypad.pinLength, (index) {
130	          final filled = index < filledCount;
131	          return Padding(
132	            padding: EdgeInsets.symmetric(
